def evaluate_small_intestine_matrix(bia_data, lab_data, input_sym):
    if lab_data['potassium_leak'] > 5.2 and lab_data['calprotectin'] > 200:
        if 'SYM-031' in input_sym or 'SYM-cachexia' in input_sym:
            return {'membrane_status': 'CRITICAL_MITOCHONDRIAL_CRASH_MD3', 'prohibited_interventions': ['Zalmanov_Yellow_Baths', 'Mechanical_Vibration_KiVI', 'H2O2_Oxidative_Protocol', 'High_Dose_Aggressive_Purgatives'], 'mandatory_protocol': ['Compounded_Cholesterol_2.5_IM', 'NAC_2400mg_Daily', 'Low_Dose_Prednisone_07AM', 'Liposomal_Vitamin_E_800IE']}
    if lab_data['mda_level'] < 0.8 and lab_data['homa_ir'] > 2.5:
        if 'SYM-035' in input_sym or 'SYM-obesity-visc' in input_sym:
            return {'membrane_status': 'STAGNANT_STEROL_OVERLOAD_MA2', 'prohibited_interventions': ['Zalmanov_White_Emulsion', 'IF_Prolonged_Fasting', 'Calcium_Carbonate_Without_K2'], 'mandatory_protocol': ['Zalmanov_Yellow_Baths_41C', 'KiVI_Vibration_7Hz_Umbilical_Zone', 'Phosphatidylcholine_2.4g_Daily', 'Magnesium_Citrate_600mg_PM']}
    if lab_data['tgf_beta1'] > 6.5 and 'SYM-172' in input_sym:
        return {'membrane_status': 'SCLEROTIC_MATRIX_FIBROSIS_MS', 'prohibited_interventions': ['Aggressive_Catalytic_Oxidants', 'High_Dose_Ascorbic_Acid_IV'], 'mandatory_protocol': ['Serratiopeptidase_120000SU_Fasting', 'Nattokinase_4000FU_PM', 'KiVI_Piezoelectric_Fibrolysis_40Hz_Abdominal', 'Mixed_Zalmanov_Baths_1to1']}
    return {'membrane_status': 'PHYSIOLOGICAL_OPTIMUM_M0'}
